// DNS correlation v1: state is intentionally small and workflow-local.
// This endpoint receives only compact *current* observations. Probe authority stays
// with the monitors; this workflow derives cross-vantage condition transitions.
const body = $json.body ?? $json;
const nowMs = Date.now();
const now = new Date(nowMs).toISOString();
const INTERNAL = 'internal-dns-monitor';
const EXTERNAL = 'external-dns-resilience';
const ACCEPTED = new Set([INTERNAL, EXTERNAL]);
const CONDITION_NAMES = [
  'dns_service_impact',
  'individual_resolver_degradation',
  'lan_resolver_selection_failure',
  'external_path_impairment',
  'midway_recursion_instability',
  'internal_observer_stale',
];
// Midway-only evidence and observer freshness are retained for correlation and reports,
// but neither alone establishes a user-impacting DNS incident.
const ACTIONABLE = new Set(CONDITION_NAMES.filter(name => !['midway_recursion_instability', 'internal_observer_stale'].includes(name)));
const FRESH_MS = 6 * 60 * 1000;
const BOOTSTRAP_GRACE_MS = 6 * 60 * 1000;
const RETENTION_MS = 48 * 60 * 60 * 1000;
const MAX_OBSERVERS = 8;
const MAX_DELIVERIES = 32;
// Closed episodes are compact correlated evidence, not raw telemetry.
const HISTORY_RETENTION_MS = 35 * 24 * 60 * 60 * 1000;
const MAX_EPISODE_HISTORY = 512;

function reject(message, details = {}) {
  return [{ json: {
    responseCode: 400,
    response: { accepted: false, error: 'invalid_dns_observation', message, details },
    deliveryQueue: [],
  }}];
}
function bool(value) { return typeof value === 'boolean'; }
function validExecution(value) {
  return value && typeof value === 'object' &&
    typeof value.host === 'string' && value.host.length > 0 &&
    typeof value.vantage === 'string' && value.vantage.length > 0;
}
function observerSummary(source, checks) {
  if (source === INTERNAL) return {
    client_path: checks.client_path,
    resolvers: { pihole_a: checks.resolvers.pihole_a, pihole_b: checks.resolvers.pihole_b },
  };
  return {
    external_path: checks.external_path,
    resolvers: { pihole_a: checks.resolvers.pihole_a, pihole_b: checks.resolvers.pihole_b },
    midway_recursion: checks.midway_recursion,
  };
}

if (!body || typeof body !== 'object' || Array.isArray(body)) return reject('Body must be one observation object');
const required = ['contract_version', 'source', 'observed_at', 'sequence', 'execution', 'checks'];
const missing = required.filter(key => body[key] === undefined || body[key] === null || body[key] === '');
if (missing.length) return reject('Missing required fields', { missing });
if (body.contract_version !== '1.0') return reject('Unsupported contract_version', { expected: '1.0' });
if (!ACCEPTED.has(body.source)) return reject('Unsupported source', { accepted_sources: [...ACCEPTED] });
if (!Number.isSafeInteger(body.sequence) || body.sequence < 0) return reject('sequence must be a non-negative integer');
if (!validExecution(body.execution)) return reject('execution.host and execution.vantage are required strings');
const observedMs = Date.parse(body.observed_at);
if (!Number.isFinite(observedMs) || observedMs > nowMs + 5 * 60 * 1000) return reject('observed_at must be ISO-8601 and not more than five minutes in the future');
const checks = body.checks;
if (!checks || typeof checks !== 'object' || !checks.resolvers || typeof checks.resolvers !== 'object') return reject('checks.resolvers is required');
if (!bool(checks.resolvers.pihole_a) || !bool(checks.resolvers.pihole_b)) return reject('checks.resolvers.pihole_a and checks.resolvers.pihole_b must be booleans');
if (body.source === INTERNAL) {
  // Critical policy boundary: ordinary IX/LAN clients must not query Midway directly.
  if (Object.hasOwn(checks, 'midway_recursion')) return reject('Internal observations must not include direct Midway evidence');
  if (!bool(checks.client_path)) return reject('Internal observations require checks.client_path boolean');
}
if (body.source === EXTERNAL) {
  if (!bool(checks.external_path) || !bool(checks.midway_recursion)) return reject('External observations require checks.external_path and checks.midway_recursion booleans');
}

const store = $getWorkflowStaticData('global');
if (!Number.isInteger(store.schema) || store.schema < 1) {
  // Only bounded state: latest observer summaries, six condition episodes, and a
  // short delivery audit. This intentionally replaces unavailable Data Tables.
  Object.assign(store, {
    schema: 1,
    bootstrapped_at: now,
    observers: {},
    conditions: {},
    pending_events: {},
    delivered_event_ids: {},
    delivery_audit: [],
  });
}
store.observers ??= {};
store.conditions ??= {};
store.pending_events ??= {};
store.delivered_event_ids ??= {};
store.delivery_audit ??= [];
if (store.schema < 2) {
  // Schema 2 adds bounded, correlated episode records for daily reporting. The
  // prior schema deliberately retained only live state, so it cannot fabricate
  // durations before this migration.
  store.episode_history ??= [];
  store.report_outbox ??= {};
  store.delivered_reports ??= {};
  store.report_audit ??= [];
  for (const episode of Object.values(store.conditions)) {
    if (episode?.open && !episode.opened_at) episode.opened_at = episode.changed_at ?? now;
  }
  store.schema = 2;
}
store.episode_history ??= [];
store.episode_history_started_at ??= now;
store.report_outbox ??= {};
store.delivered_reports ??= {};
store.report_audit ??= [];
for (const [condition, episode] of Object.entries(store.conditions)) {
  if (episode?.open && !episode.opened_at) episode.opened_at = episode.changed_at ?? now;
}
store.episode_history = store.episode_history
  .filter(record => Number.isFinite(Date.parse(record.closed_at ?? record.opened_at)) &&
    nowMs - Date.parse(record.closed_at ?? record.opened_at) <= HISTORY_RETENTION_MS)
  .slice(-MAX_EPISODE_HISTORY);
for (const collection of [store.delivered_reports, store.report_outbox]) {
  for (const [key, entry] of Object.entries(collection)) {
    const when = entry?.delivered_at ?? entry?.queued_at ?? entry?.report?.day_start;
    if (!Number.isFinite(Date.parse(when)) || nowMs - Date.parse(when) > HISTORY_RETENTION_MS) delete collection[key];
  }
}
store.report_audit = store.report_audit.slice(-MAX_DELIVERIES);
const previous = store.observers[body.source];
if (previous && body.sequence <= previous.sequence) {
  return [{ json: {
    responseCode: 202,
    response: { accepted: true, duplicate_or_out_of_order: true, source: body.source, sequence: body.sequence },
    deliveryQueue: [],
  }}];
}

store.observers[body.source] = {
  sequence: body.sequence,
  received_at: now,
  observed_at: body.observed_at,
  execution: { host: body.execution.host, vantage: body.execution.vantage, runtime_revision: body.execution.runtime_revision ?? null },
  checks: observerSummary(body.source, checks),
};
// Prune old/unknown observers and hard-bound retention even if new sources are added later.
for (const [source, observer] of Object.entries(store.observers)) {
  if (!Number.isFinite(Date.parse(observer.received_at)) || nowMs - Date.parse(observer.received_at) > RETENTION_MS) delete store.observers[source];
}
const orderedSources = Object.entries(store.observers).sort((a, b) => Date.parse(b[1].received_at) - Date.parse(a[1].received_at));
for (const [source] of orderedSources.slice(MAX_OBSERVERS)) delete store.observers[source];

const internal = store.observers[INTERNAL];
const external = store.observers[EXTERNAL];
const internalFresh = Boolean(internal) && nowMs - Date.parse(internal.received_at) <= FRESH_MS;
const desired = Object.fromEntries(CONDITION_NAMES.map(name => [name, false]));

if (internalFresh) {
  const i = internal.checks;
  if (!i.client_path) {
    // A failed client path with both direct Pi-hole checks healthy is resolver
    // selection/path trouble, not evidence that the DNS service itself is down.
    if (i.resolvers.pihole_a && i.resolvers.pihole_b) desired.lan_resolver_selection_failure = true;
    else desired.dns_service_impact = true;
  } else if (i.resolvers.pihole_a !== i.resolvers.pihole_b) {
    desired.individual_resolver_degradation = true;
  }
} else if (nowMs - Date.parse(store.bootstrapped_at) >= BOOTSTRAP_GRACE_MS) {
  // Loss of LAN-side corroboration is observable only when a webhook call arrives.
  desired.internal_observer_stale = true;
}

if (external) {
  const e = external.checks;
  if (!e.external_path && internalFresh && internal.checks.client_path) {
    desired.external_path_impairment = true;
  }
  // The only permitted direct Midway evidence is from the external observer.
  // It is diagnostic only and does not become an operational-ingress event.
  if (!e.midway_recursion && internalFresh && internal.checks.client_path &&
      internal.checks.resolvers.pihole_a && internal.checks.resolvers.pihole_b) {
    desired.midway_recursion_instability = true;
  }
}

function eventFor(condition, transition, episode, evidence) {
  const open = transition === 'opened';
  return {
    contract_version: '1.0',
    event_id: `dns-correlation-state:${condition}:${transition}:${episode}`,
    incident_key: `dns-correlation-state:${condition}`,
    source: 'dns-correlation-state',
    owner: 'network',
    category: 'dns',
    severity: condition === 'dns_service_impact' ? 'critical' : 'warning',
    state: open ? 'degraded' : 'healthy',
    transition,
    title: `${condition.replaceAll('_', ' ')} ${transition}`,
    message: open
      ? `DNS correlation opened ${condition} from compact current observations.`
      : `DNS correlation recovered ${condition} from compact current observations.`,
    occurred_at: now,
    execution: { host: 'n8n', vantage: 'dns-correlation-state', runtime_revision: 'workflow-staticdata-v1' },
    details: { condition, episode, evidence },
  };
}
function queuePending(event) {
  if (store.delivered_event_ids[event.event_id]) return;
  store.pending_events[event.event_id] ??= { event, queued_at: now };
}

function compactVantages(correlationEvidence) {
  const seen = new Set();
  return Object.entries(correlationEvidence?.observers ?? {})
    .map(([source, observer]) => ({ source, host: observer.execution?.host ?? 'unknown', vantage: observer.execution?.vantage ?? 'unknown' }))
    .filter(item => {
      const key = `${item.source}:${item.host}:${item.vantage}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}
function recordClosedEpisode(condition, episode, correlationEvidence) {
  const openedAt = episode.opened_at ?? episode.changed_at ?? now;
  const openedMs = Date.parse(openedAt);
  const closedMs = nowMs;
  store.episode_history.push({
    condition,
    episode: episode.episode,
    actionable: ACTIONABLE.has(condition),
    opened_at: openedAt,
    closed_at: now,
    duration_ms: Number.isFinite(openedMs) ? Math.max(0, closedMs - openedMs) : 0,
    vantages: compactVantages(correlationEvidence),
  });
  store.episode_history = store.episode_history.slice(-MAX_EPISODE_HISTORY);
  delete episode.opened_at;
}

const transitions = [];
let deliveryQueue = [];
const diagnosticTransitions = [];
const evidence = {
  received_source: body.source,
  received_sequence: body.sequence,
  internal_fresh: internalFresh,
  observers: Object.fromEntries(Object.entries(store.observers).map(([source, o]) => [source, {
    observed_at: o.observed_at, execution: o.execution, checks: o.checks,
  }])),
};
for (const condition of CONDITION_NAMES) {
  const episode = store.conditions[condition] ?? { open: false, episode: 0 };
  const open = Boolean(episode.open);
  if (open === desired[condition]) continue;
  const transition = desired[condition] ? 'opened' : 'recovered';
  if (desired[condition]) {
    episode.episode += 1;
    episode.opened_at = now;
  } else {
    recordClosedEpisode(condition, episode, evidence);
  }
  episode.open = desired[condition];
  episode.changed_at = now;
  episode.last_evidence = evidence;
  store.conditions[condition] = episode;
  const transitionRecord = { condition, transition, episode: episode.episode, occurred_at: now };
  transitions.push(transitionRecord);
  if (!ACTIONABLE.has(condition)) {
    diagnosticTransitions.push(transitionRecord);
    continue;
  }
  queuePending(eventFor(condition, transition, episode.episode, evidence));
}
// Backfill any current open episode lacking a recorded ingress acceptance. This
// recovers pre-outbox state safely: ingress deduplicates the stable event ID.
for (const condition of CONDITION_NAMES) {
  const episode = store.conditions[condition];
  if (ACTIONABLE.has(condition) && episode?.open && episode.episode > 0) {
    queuePending(eventFor(condition, 'opened', episode.episode, episode.last_evidence ?? evidence));
  }
}
deliveryQueue = Object.values(store.pending_events)
  .sort((a, b) => String(a.queued_at).localeCompare(String(b.queued_at)))
  .map(entry => entry.event);

return [{ json: {
  responseCode: 202,
  response: {
    accepted: true,
    source: body.source,
    sequence: body.sequence,
    derived_conditions: Object.entries(desired).filter(([, open]) => open).map(([name]) => name),
    transitions,
    promoted_count: deliveryQueue.length,
    unalerted_diagnostic_transitions: diagnosticTransitions,
  },
  deliveryQueue,
}}];

// The response was already sent (202/400). Emit only actionable transition events.
const result = $('Correlate Current Observation').first().json;
if (result.responseCode !== 202 || !Array.isArray(result.deliveryQueue)) return [];
return result.deliveryQueue.map(event => ({ json: { event } }));

// Acknowledgement is durable workflow state, separate from condition truth.
const store = $getWorkflowStaticData('global');
store.pending_events ??= {};
store.delivered_event_ids ??= {};
store.delivery_audit ??= [];
const event = $('Expand Actionable Transition Events').item.json.event;
delete store.pending_events[event.event_id];
store.delivered_event_ids[event.event_id] = new Date().toISOString();
const delivered = Object.entries(store.delivered_event_ids).sort((a, b) => String(a[1]).localeCompare(String(b[1])));
for (const [eventId] of delivered.slice(0, Math.max(0, delivered.length - 32))) delete store.delivered_event_ids[eventId];
store.delivery_audit.push({ event_id: event.event_id, result: 'accepted_by_ingress', at: new Date().toISOString() });
if (store.delivery_audit.length > 32) store.delivery_audit.splice(0, store.delivery_audit.length - 32);
return [{ json: { recorded: true, event_id: event.event_id } }];

// Retain the exact event for a later current observation; never regenerate an ID.
const store = $getWorkflowStaticData('global');
store.pending_events ??= {};
store.delivery_audit ??= [];
const event = $('Expand Actionable Transition Events').item.json.event;
store.pending_events[event.event_id] ??= { event, queued_at: new Date().toISOString() };
store.delivery_audit.push({ event_id: event.event_id, result: 'ingress_delivery_failed', at: new Date().toISOString(), node: $json.error?.node?.name ?? 'HTTP Request' });
if (store.delivery_audit.length > 32) store.delivery_audit.splice(0, store.delivery_audit.length - 32);
return [{ json: { recorded: true, result: 'ingress_delivery_failed', event_id: event.event_id } }];

// Cadenced report builder: runs inside the correlation workflow so it can read the
// same bounded static state that owns DNS episode truth. No probe, observer, or
// raw-telemetry store is introduced here.
const store = $getWorkflowStaticData('global');
const ZONE = 'America/New_York';
const REPORT_RETENTION_MS = 35 * 24 * 60 * 60 * 1000;
const MAX_REPORTS = 35;
const LABELS = {
  dns_service_impact: { label: 'Household DNS impact', class: 'user-impacting/actionable' },
  individual_resolver_degradation: { label: 'Resolver redundancy incidents', class: 'actionable' },
  lan_resolver_selection_failure: { label: 'LAN resolver-selection failures', class: 'user-impacting/actionable' },
  external_path_impairment: { label: 'External-path impairments', class: 'actionable external-vantage evidence' },
  midway_recursion_instability: { label: 'Midway fresh-recursion instability', class: 'diagnostic-only; internal client impact is not implied' },
  internal_observer_stale: { label: 'Internal-observer stale periods', class: 'observer-assurance; not direct client impact' },
};
function duration(ms) {
  const minutes = Math.max(0, Math.round(ms / 60000));
  if (minutes < 60) return `${minutes}m`;
  const hours = Math.floor(minutes / 60);
  return `${hours}h${minutes % 60 ? ` ${minutes % 60}m` : ''}`;
}
function vantages(records) {
  const values = new Set();
  for (const record of records) for (const item of record.vantages ?? []) {
    values.add(`${item.host} / ${item.vantage}`);
  }
  return [...values].sort();
}
store.episode_history ??= [];
store.report_outbox ??= {};
store.delivered_reports ??= {};
store.report_audit ??= [];
const now = DateTime.now().setZone(ZONE);
const cadence = String($json.report_cadence ?? 'daily');
let dayEnd = now.startOf('day');
let dayStart = dayEnd.minus({ days: 1 });
let displayPeriod = dayStart.toISODate();
if (cadence === 'weekly') {
  // The weekly schedule runs Monday morning and summarizes the prior Mon–Sun week.
  dayEnd = now.startOf('day');
  dayStart = dayEnd.minus({ days: 7 });
  displayPeriod = `${dayStart.toISODate()} – ${dayEnd.minus({ days: 1 }).toISODate()}`;
} else if (cadence === 'monthly') {
  // The monthly schedule runs on the first and summarizes the prior calendar month.
  dayEnd = now.startOf('month');
  dayStart = dayEnd.minus({ months: 1 }).startOf('month');
  displayPeriod = dayStart.toFormat('LLLL yyyy');
} else if (cadence !== 'daily') {
  throw new Error(`Unsupported report cadence: ${cadence}`);
}
const dayKey = dayStart.toISODate();
const reportKey = `${cadence}:${dayKey}`;
const startMs = dayStart.toMillis();
const endMs = dayEnd.toMillis();
for (const [key, entry] of Object.entries(store.delivered_reports)) {
  const at = Date.parse(entry.delivered_at ?? entry.report?.day_start);
  if (!Number.isFinite(at) || now.toMillis() - at > REPORT_RETENTION_MS) delete store.delivered_reports[key];
  else if (entry.delivery_verified !== true) {
    // Schema-2 reporting was introduced while an earlier proof path was being
    // corrected. Never let an unverified acknowledgement suppress a report.
    store.report_outbox[key] ??= { report: entry.report, queued_at: now.toUTC().toISO() };
    delete store.delivered_reports[key];
  }
}
for (const [key, entry] of Object.entries(store.report_outbox)) {
  const at = Date.parse(entry.queued_at ?? entry.report?.day_start);
  if (!Number.isFinite(at) || now.toMillis() - at > REPORT_RETENTION_MS) delete store.report_outbox[key];
}
// A retained failed report is retried before composing a newer day. This keeps
// delivery state distinct from episode truth without adding a polling loop.
const pending = Object.entries(store.report_outbox)
  .sort((a, b) => String(a[1].queued_at).localeCompare(String(b[1].queued_at)))[0];
if (pending) return [{ json: pending[1].report }];
if (store.delivered_reports[reportKey]) return [];
const records = [];
for (const record of store.episode_history) {
  const opened = Date.parse(record.opened_at);
  const closed = Date.parse(record.closed_at);
  if (!Number.isFinite(opened) || !Number.isFinite(closed) || closed <= startMs || opened >= endMs) continue;
  records.push({ ...record, overlap_ms: Math.max(0, Math.min(closed, endMs) - Math.max(opened, startMs)) });
}
for (const [condition, episode] of Object.entries(store.conditions ?? {})) {
  if (!episode?.open) continue;
  const opened = Date.parse(episode.opened_at ?? episode.changed_at);
  if (!Number.isFinite(opened) || opened >= endMs) continue;
  records.push({
    condition, episode: episode.episode, actionable: condition !== 'midway_recursion_instability',
    opened_at: new Date(opened).toISOString(), closed_at: dayEnd.toUTC().toISO(),
    overlap_ms: Math.max(0, endMs - Math.max(opened, startMs)),
    vantages: Object.entries(episode.last_evidence?.observers ?? {}).map(([source, observer]) => ({
      source, host: observer.execution?.host ?? 'unknown', vantage: observer.execution?.vantage ?? 'unknown',
    })),
    open_at_report_end: true,
  });
}
const summaries = Object.entries(LABELS).map(([condition, meta]) => {
  const episodes = records.filter(record => record.condition === condition);
  const total = episodes.reduce((sum, record) => sum + record.overlap_ms, 0);
  const longest = episodes.reduce((max, record) => Math.max(max, record.overlap_ms), 0);
  return { condition, ...meta, count: episodes.length, total_ms: total, longest_ms: longest, vantages: vantages(episodes) };
});
const historyStartedMs = Date.parse(store.episode_history_started_at);
const coverage = Number.isFinite(historyStartedMs) && historyStartedMs > startMs
  ? `Episode-history coverage began ${new Date(historyStartedMs).toISOString()}; durations before that point are not inferred.`
  : null;
const actionable = summaries.filter(item => item.class.includes('actionable') && item.count > 0);
const diagnostic = summaries.filter(item => item.condition === 'midway_recursion_instability')[0];
const lines = [
  `**DNS operational report — ${dayKey} (America/New_York)**`,
  coverage ? `_${coverage}_` : null,
  '',
  ...summaries.map(item => {
    const core = `**${item.label}:** ${item.count}`;
    if (!item.count) return `${core} — none`;
    return `${core} — total ${duration(item.total_ms)}, longest ${duration(item.longest_ms)}${item.vantages.length ? `; ${item.vantages.join(', ')}` : ''}`;
  }),
  '',
  actionable.length ? `**Actionable/user-impacting evidence:** ${actionable.map(item => item.label).join('; ')}.` : '**Actionable/user-impacting evidence:** none.',
  diagnostic?.count ? '**Diagnostic-only:** Midway fresh-recursion instability did not by itself establish internal client impact.' : '**Diagnostic-only:** no Midway fresh-recursion instability.',
].filter(Boolean);
const report = {
  report_key: reportKey,
  report_kind: `${cadence}_dns_operational_report`,
  cadence,
  display_period: displayPeriod,
  day_start: dayStart.toUTC().toISO(),
  day_end: dayEnd.toUTC().toISO(),
  generated_at: now.toUTC().toISO(),
  text: lines.join('\n'),
  summaries,
  coverage_note: coverage,
};
store.report_outbox[reportKey] = { report, queued_at: report.generated_at };
store.report_audit.push({ report_key: reportKey, result: 'queued', at: report.generated_at });
store.report_audit = store.report_audit.slice(-MAX_REPORTS);
return [{ json: report }];

values.json:
={{ (() => {
  const report = $('Build DNS Operational Report').first().json;
  const cadence = report.cadence || 'daily';
  const palette = {
    daily: { title: `Daily DNS Report for ${report.display_period}`, color: 3447003 },
    weekly: { title: `Weekly DNS Report for ${report.display_period}`, color: 10181046 },
    monthly: { title: `Monthly DNS Report for ${report.display_period}`, color: 15844367 },
  }[cadence];
  if (!palette) throw new Error(`Unsupported report cadence: ${cadence}`);
  const summaries = Object.fromEntries((report.summaries || []).map(item => [item.condition, item]));
  const get = key => summaries[key] || { count: 0, total_ms: 0, longest_ms: 0, vantages: [] };
  const duration = ms => {
    const minutes = Math.max(0, Math.round(Number(ms || 0) / 60000));
    if (minutes < 60) return `${minutes}m`;
    const hours = Math.floor(minutes / 60);
    return `${hours}h${minutes % 60 ? ` ${minutes % 60}m` : ''}`;
  };
  const metric = (key, label) => {
    const item = get(key);
    if (!item.count) return `${label}: 0`;
    const lines = [`${label}: ${item.count} • ${duration(item.total_ms)} total • ${duration(item.longest_ms)} longest`];
    if (item.vantages?.length) lines.push(`Vantage: ${item.vantages.join(', ')}`);
    return lines.join('\n');
  };
  const actionable = [
    ['dns_service_impact', 'Household DNS'],
    ['individual_resolver_degradation', 'Resolver redundancy'],
    ['lan_resolver_selection_failure', 'LAN resolver selection'],
    ['external_path_impairment', 'External path'],
  ].filter(([key]) => get(key).count).map(([, label]) => label);
  const midway = get('midway_recursion_instability');
  return JSON.stringify({
    title: palette.title,
    color: palette.color,
    fields: [
      { name: '🏠 Household DNS', value: metric('dns_service_impact', 'Incidents'), inline: false },
